vec3 getColor(vec2 p) {
    // Map to screen and get radius
    p = 2. * (2. * p - iResolution.xy) / iResolution.y;
    vec2 r = .1 + iMouse.xy / iResolution.xy;

    // Invert in ellipse
    float fac = .5;
    vec2 rr = r * r, pp = p * p;
    if (rr.y * pp.x + rr.x * pp.y > rr.x * rr.y) {
        p *= rr.x * rr.y / dot(pp, rr.yx);
        fac = 1.;
    }

    // Get color
    return texture(iChannel0, p + .1 * iTime).xyz * fac;
}

void mainImage(out vec4 fragColor, in vec2 p) {
    vec3 col = getColor(p);
    col += getColor(p + vec2(.5, 0.));
    col += getColor(p + vec2(-.5, 0.));
    col += getColor(p + vec2(0., .5));
    col += getColor(p + vec2(0., -.5));
    fragColor = vec4(.2 * col, 1.);
}
